// Generated by tools/build-pwa.js. Caches the app so it opens without signal. Data calls (POST to Apps Script) are never cached or intercepted.
const CACHE = 'fsx-7d31cdf355';
const SHELL = ['./', 'index.html', 'config.js', 'engine.js', 'manifest.webmanifest', 'icon-192.png', 'icon-512.png'];
self.addEventListener('install', function (e) { e.waitUntil(caches.open(CACHE).then(function (c) { return c.addAll(SHELL); }).then(function () { return self.skipWaiting(); })); });
self.addEventListener('activate', function (e) {
  e.waitUntil(caches.keys().then(function (keys) { return Promise.all(keys.filter(function (k) { return k.indexOf('fsx-') === 0 && k !== CACHE; }).map(function (k) { return caches.delete(k); })); }).then(function () { return self.clients.claim(); }));
});
self.addEventListener('fetch', function (e) {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const sameOrigin = url.origin === self.location.origin, font = /(^|\.)(googleapis|gstatic)\.com$/.test(url.hostname);
  if (!sameOrigin && !font) return;
  e.respondWith(caches.open(CACHE).then(function (cache) {
    return cache.match(req, { ignoreSearch: true }).then(function (hit) {
      const net = fetch(req).then(function (res) { if (res && (res.ok || res.type === 'opaque')) cache.put(req, res.clone()); return res; }).catch(function () { return hit || (req.mode === 'navigate' ? cache.match('index.html') : undefined); });
      return hit || net;   // instant from the phone, updated in the background for next time
    });
  }));
});

// Background work of the service worker (Android Chrome): with the app CLOSED the phone still
//   - sends what waits to go (spray events and plucking of the old queue, and the operations made on the phone's own copy) as soon as signal returns   ('sync' event)
//   - fetches the changes of the server into a staging area, so the next time the app opens its copy is already current                             ('periodicsync' event)
// It does only what needs the network and the phone's storage; the phone's database engine applies the staged changes when the app opens (nothing here changes the copy itself).
// The answers are written to a ledger the page reads: the page is the only one that changes its own outbox, so nothing is written from two sides.
// Shared storage: IndexedDB 'fsx-sync' / store 'kv' (the page's Kv). Keys:  current {uid, endpoint}   device:<uid> {key}   outbox:<uid> [items]   ops:<uid> [operations]
//   ledger:<uid> {itemId: {ok, error, code}}   opledger:<uid> {opId: inner answer}   staged:<uid> [pull answers]   swstate:<uid> {since, epoch, scope}   needcopy:<uid> true
// This file is pasted into sw.js by tools/build-pwa.js (and loaded by tests/sw.js the same way), so it must not use anything but the service worker's own globals.
var FSX_FINAL = { VALIDATION: 1, FORBIDDEN: 1, ERROR: 1 }; // a refusal the server will always repeat: the entry is flagged, not retried
var FSX_STAGE_MAX = 200;

var FsxKv = (function () {
  var dbp = null;
  function db() {
    if (!dbp)
      dbp = new Promise(function (res, rej) {
        var q = indexedDB.open('fsx-sync', 1);
        q.onupgradeneeded = function () {
          q.result.createObjectStore('kv');
        };
        q.onsuccess = function () {
          res(q.result);
        };
        q.onerror = function () {
          rej(q.error);
        };
      });
    return dbp;
  }
  function tx(mode, fn) {
    return db().then(function (d) {
      return new Promise(function (res, rej) {
        var t = d.transaction('kv', mode),
          out = fn(t.objectStore('kv'));
        t.oncomplete = function () {
          res(out && out.result !== undefined ? out.result : undefined);
        };
        t.onerror = t.onabort = function () {
          rej(t.error);
        };
      });
    });
  }
  return {
    get: function (k, dflt) {
      return tx('readonly', function (os) {
        return os.get(k);
      }).then(
        function (v) {
          return v === undefined ? dflt : v;
        },
        function () {
          return dflt;
        }
      );
    },
    set: function (k, v) {
      return tx('readwrite', function (os) {
        os.put(v, k);
      });
    }
  };
})();

function fsxPost(endpoint, fn, args) {
  return fetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    body: JSON.stringify({ fn: fn, args: args }),
    redirect: 'follow',
    credentials: 'omit'
  }).then(function (r) {
    return r.json();
  });
}

/** Send what waits. Stops at the first thing that needs signal or a login; an answer (done, or refused for good) goes in the ledger. */
function fsxUpload(cur, key) {
  var uid = cur.uid;
  return Promise.all([
    FsxKv.get('outbox:' + uid, []),
    FsxKv.get('ops:' + uid, []),
    FsxKv.get('ledger:' + uid, {}),
    FsxKv.get('opledger:' + uid, {})
  ]).then(function (v) {
    var outbox = v[0].filter(function (it) {
        return !it.failed && !v[2][it.id];
      }),
      ops = v[1].filter(function (op) {
        return !v[3][op.id];
      }),
      ledger = v[2],
      opledger = v[3];
    var work = [];
    outbox.forEach(function (it) {
      work.push({
        id: it.id,
        fn: it.event ? 'api_saveSprayEvent' : 'api_savePluck',
        args: [it.event ? it.event : { date: it.date, lines: it.lines }],
        done: function (inner) {
          ledger[it.id] = inner.ok ? { ok: true } : { ok: false, error: inner.error || 'The server did not accept it.', code: inner.code };
        }
      });
    });
    ops.forEach(function (op) {
      work.push({
        id: op.id,
        fn: op.fn,
        args: op.args,
        done: function (inner) {
          opledger[op.id] = inner;
        }
      });
    });
    function next(i) {
      if (i >= work.length) return Promise.resolve(true);
      var w = work[i];
      return fsxPost(cur.endpoint, 'api_submitOp', [key, w.id, w.fn, w.args]).then(function (env) {
        if (!env || !env.ok) return false; // busy, the key is gone, an unexpected error: leave everything for the page (or the next try)
        var inner = env.data;
        if (!(inner && (inner.ok || FSX_FINAL[inner.code]))) return false;
        w.done(inner);
        return Promise.all([FsxKv.set('ledger:' + uid, ledger), FsxKv.set('opledger:' + uid, opledger)]).then(function () {
          return next(i + 1);
        });
      });
    }
    return next(0);
  });
}

/** Ask the server what changed since the last time (the engine's own last pull, or this worker's) and keep the answer for the page. */
function fsxPull(cur, key) {
  var uid = cur.uid;
  return Promise.all([FsxKv.get('swstate:' + uid, null), FsxKv.get('staged:' + uid, []), FsxKv.get('engine-meta:' + uid, null)]).then(function (v) {
    var st = v[0] && v[2] ? (v[0].since >= v[2].since ? v[0] : v[2]) : v[0] || v[2]; // the newer of this worker's last pull and the engine's last pull
    if (!st || !st.since) return false; // no copy yet: the page makes it
    return fsxPost(cur.endpoint, 'api_syncPull', [key, st.since, st.epoch, st.scope]).then(function (env) {
      if (!env || !env.ok) return false;
      var res = env.data;
      if (res.snapshot)
        return FsxKv.set('needcopy:' + uid, true).then(function () {
          return true;
        });
      var n = Object.keys(res.rows).length + Object.keys(res.deleted).length;
      var staged = v[1];
      if (n) {
        staged.push(res);
        if (staged.length > FSX_STAGE_MAX)
          return FsxKv.set('needcopy:' + uid, true).then(function () {
            return FsxKv.set('staged:' + uid, []);
          });
      }
      return Promise.all([
        FsxKv.set('staged:' + uid, staged),
        FsxKv.set('swstate:' + uid, { since: res.now, epoch: res.epoch, scope: res.scope })
      ]).then(function () {
        return true;
      });
    });
  });
}

function fsxBackground(what) {
  return FsxKv.get('current', null).then(function (cur) {
    if (!cur || !cur.uid || !cur.endpoint) return false;
    return FsxKv.get('device:' + cur.uid, null).then(function (dev) {
      if (!dev || !dev.key) return false;
      var job =
        what === 'pull'
          ? fsxUpload(cur, dev.key).then(function () {
              return fsxPull(cur, dev.key);
            })
          : fsxUpload(cur, dev.key);
      return job.then(function (ok) {
        return self.clients.matchAll({ includeUncontrolled: true }).then(function (list) {
          list.forEach(function (c) {
            c.postMessage({ fsx: 'background-done', what: what });
          });
          return ok;
        });
      });
    });
  });
}
self.addEventListener('sync', function (e) {
  if (e.tag === 'fsx-send') e.waitUntil(fsxBackground('send'));
});
self.addEventListener('periodicsync', function (e) {
  if (e.tag === 'fsx-pull') e.waitUntil(fsxBackground('pull'));
});
